// nsIStoreCompactListener callback invoked when the compaction starts.
NS_IMETHODIMP FolderCompactor::OnCompactionBegin() {
  MOZ_ASSERT(mDB);
  MOZ_ASSERT(mPaths.Source);
  MOZ_ASSERT(mPaths.Compacting);
  MOZ_ASSERT(mPaths.Compacted);
  MOZ_ASSERT(mPaths.Backup);

  if (ShutdownObserver::IsShuttingDown()) {
    return NS_ERROR_ABORT;
  }

  MOZ_LOG(gCompactLog, LogLevel::Verbose, ("OnCompactionBegin()"));
  mTimerId = mozilla::glean::mail::compact_duration.Start();

  PROFILER_MARKER_TEXT(
      "FolderCompactor", MAILNEWS,
      mozilla::MarkerOptions(mozilla::MarkerTiming::IntervalStart()),
      mFolder->URI());
  return NS_OK;

nsPrintfCString statusStr("%x", (uint32_t)status);
mozilla::glean::mail::compact_result.Get(statusStr).Add(1);
if (mTimerId) {
  mozilla::glean::mail::compact_duration.StopAndAccumulate(
      std::move(mTimerId));
  PROFILER_MARKER_TEXT(
      "FolderCompactor", MAILNEWS,
      mozilla::MarkerOptions(mozilla::MarkerTiming::IntervalEnd()),
      mFolder->URI());
}

if (NS_SUCCEEDED(status)) {
  mozilla::glean::mail::compact_space_recovered.Accumulate(oldSize - newSize);
}

const listener = new PromiseTestUtils.PromiseUrlListener();
gFolder2.compact(listener, null);

// Shut down (or pretend to)! This can happen after starting compact because
// compact is event driven and we haven't released the event loop yet.
Services.obs.notifyObservers(null, "test-quit-application");
await Assert.rejects(
  listener.promise,
  /2147500036/,
  "compact should exit with NS_ERROR_ABORT"
);

Assert.equal(
  Glean.mail.compactResult[Cr.NS_OK.toString(16)].testGetValue(),
  null,
  "success result should not be recorded in Glean"
);
Assert.equal(
  Glean.mail.compactResult[Cr.NS_ERROR_ABORT.toString(16)].testGetValue(),
  1,
  "abort result should be recorded in Glean"
);
Assert.equal(
  Glean.mail.compactDuration.testGetValue(),
  null,
  "duration should not be recorded in Glean"
);
Assert.equal(
  Glean.mail.compactSpaceRecovered.testGetValue(),
  null,
  "bytes saved should not be recorded in Glean"
